package org.apache.commons.math.stat.correlation;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.distribution.TDistribution;
import org.apache.commons.math.distribution.TDistributionImpl;
import org.apache.commons.math.linear.BlockRealMatrix;
import org.apache.commons.math.linear.RealMatrix;
import org.apache.commons.math.stat.regression.SimpleRegression;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathIllegalStateException;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for PearsonsCorrelation#getCorrelationPValues
 */
public class PearsonsCorrelation_getCorrelationPValues_TriageGen3Test {

    private static final double EPSILON = 1e-9;

    @Test
    public void testGetCorrelationPValues_StandardCase() {
        // Two variables with a perfect correlation (r=1)
        // Note: r=1 leads to division by zero in the formula (1 - r*r)
        // However, in practice, we use data that results in high but not exactly 1.0 to avoid NaN issues 
        // or test the mathematical behavior.
        double[][] data = {
            {1.0, 2.0, 3.0},
            {1.0, 2.1, 2.9}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        Assert.assertEquals(2, pValues.getRowDimension());
        Assert.assertEquals(2, pValues.getColumnDimension());

        // Diagonal should be 0.0
        Assert.assertEquals(0.0, pValues.getEntry(0, 0), EPSILON);
        Assert.assertEquals(0.0, pValues.getEntry(1, 1), EPSILON);

        // Off-diagonal should be symmetric
        Assert.assertEquals(pValues.getEntry(0, 1), pValues.getEntry(1, 0), EPSILON);
        // P-value should be > 0
        Assert.assertTrue(pValues.getEntry(0, 1) > 0);
    }

    @Test
    public void testGetCorrelationPValues_IdentityMatrix() {
        // Data where variables are uncorrelated
        double[][] data = {
            {1.0, 0.0, 1.0},
            {0.0, 1.0, 1.0},
            {1.0, 1.0, 0.0}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        Assert.assertEquals(3, pValues.getRowDimension());
        for (int i = 0; i < 3; i++) {
            Assert.assertEquals(0.0, pValues.getEntry(i, i), EPSILON);
        }
    }

    @Test
    public void testGetCorrelationPValues_PerfectCorrelation() {
        // Testing edge case where r = 1.0 or -1.0
        // t = |r * sqrt((n-2)/(1-r^2))| -> results in Infinity
        // cumulativeProbability(Infinity) = 1.0
        // 2 * (1 - 1.0) = 0.0
        double[][] data = {
            {1.0, 2.0, 3.0},
            {1.0, 2.0, 3.0}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        Assert.assertEquals(0.0, pValues.getEntry(0, 1), EPSILON);
        Assert.assertEquals(0.0, pValues.getEntry(1, 0), EPSILON);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testGetCorrelationPValues_InsufficientObservations() {
        // nObs - 2 must be > 0 for TDistribution, so nObs must be > 2
        double[][] data = {
            {1.0, 2.0},
            {2.0, 1.0}
        };
        // nObs = 2, nObs - 2 = 0. TDistribution will throw exception.
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        correlation.getCorrelationPValues();
    }

    @Test
    public void testGetCorrelationPValues_LargeDataset() {
        int nObs = 100;
        int nVars = 5;
        double[][] data = new double[nObs][nVars];
        for (int i = 0; i < nObs; i++) {
            for (int j = 0; j < nVars; j++) {
                data[i][j] = MathUtils.random(100);
            }
        }
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        Assert.assertEquals(nVars, pValues.getRowDimension());
        Assert.assertEquals(nVars, pValues.getColumnDimension());
        for (int i = 0; i < nVars; i++) {
            for (int j = 0; j < nVars; j++) {
                if (i == j) {
                    Assert.assertEquals(0.0, pValues.getEntry(i, j), EPSILON);
                } else {
                    Assert.assertTrue(pValues.getEntry(i, j) >= 0.0 && pValues.getEntry(i, j) <= 1.0);
                }
            }
        }
    }
}
